// === Tab: mySketch ===
// Spring Animation
class Spring {
  constructor(target = 0.5, stiffness = 0.15, damping = 0.8) {
    this.value = target;
    this.velocity = 0;
    this.target = target;
    this.stiffness = stiffness;
    this.damping = damping;
  }

  update() {
    const force = (this.target - this.value) * this.stiffness;
    this.velocity += force;
    this.velocity *= this.damping;
    this.value += this.velocity;
  }

  impulse(amount) {
    this.velocity += amount;
  }

  set(target) {
    this.target = target;
  }

  snapTo(value) {
    this.value = value;
    this.target = value;
    this.velocity = 0;
  }
}

let theShader;
let editorVisible = false;
let shaderEditor;
let errorDisplay;
let lastValidFrag;

let paramA, paramB, paramC;
let noiseOffsetA = 0, noiseOffsetB = 100, noiseOffsetC = 200;
let driftSpeed = 0.002;
let driftAmount = 0.3;

const vert = `
// fork of https://www.shadertoy.com/view/tXscWn

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`;

const neuralNoiseFrag = `precision highp float;

varying vec2 vTexCoord;
uniform float time;
uniform vec2 resolution;
uniform float paramA;
uniform float paramB;
uniform float paramC;

void main() {
    vec2 O = (vTexCoord * resolution - resolution * 0.5) / resolution.y;
    vec2 n = O * 0.;

    float S = mix(2., 3., paramA);
    float a = 0.;

    float angle = 0.74 + paramB * .5;
    float c = cos(angle);
    float s = sin(angle);
    mat2 m = mat2(c, -s, s, c);

    float timeSpeed = 1.0 + paramC * .5;
    float iterations = mix(20., 40., paramC);

    for(float j = 0.; j < 40.; j++){
        if(j >= iterations) break;
        O *= m;
        n *= m;
        vec2 q = O * S + n - time * timeSpeed;
        a += dot(cos(q), vec2(1.8)) / S;
        n += sin(q);
        S *= 1.2;
    }

    float l = length(O);
    vec3 col = (0.5 + 0.5 * cos(a * 2.0 + vec3(1.0 + paramC * 3.0))) / (1. + l * 0.5) * (1. - l * l * 0.1);

    gl_FragColor = vec4(col, 1.0);
}`;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();

  lastValidFrag = neuralNoiseFrag;
  theShader = createShader(vert, neuralNoiseFrag);

  paramA = new Spring(0.5, 0.08, 0.85);
  paramB = new Spring(0.5, 0.08, 0.85);
  paramC = new Spring(0.5, 0.08, 0.85);

  createEditorUI();

  midi = setupMIDI();

  midi.on('noteon', (e) => {
    const velocity = e.detail.velocity / 127;
    const note = e.detail.note;
    const param = note % 3;

    const impulseStrength = map(velocity, 0, 1, 0.1, 0.5);
    const direction = random() > 0.5 ? 1 : -1;

    switch(param) {
      case 0:
        paramA.impulse(direction * impulseStrength);
        console.log(`A impulse: ${(direction * impulseStrength).toFixed(2)}`);
        break;
      case 1:
        paramB.impulse(direction * impulseStrength);
        console.log(`B impulse: ${(direction * impulseStrength).toFixed(2)}`);
        break;
      case 2:
        paramC.impulse(direction * impulseStrength);
        console.log(`C impulse: ${(direction * impulseStrength).toFixed(2)}`);
        break;
    }
  });

  midi.onCC(1, (value) => paramA.set(value / 127));
  midi.onCC(2, (value) => paramB.set(value / 127));
  midi.onCC(3, (value) => paramC.set(value / 127));

  console.log("Neural Noise Shader Ready");
  console.log("Press 'e' to toggle editor");
}

function createEditorUI() {
  let container = createDiv();
  container.id('editor-container');
  container.style('position', 'absolute');
  container.style('top', '10px');
  container.style('left', '10px');
  container.style('width', '600px');
  container.style('max-width', '90%');
  container.style('background', 'rgba(0, 0, 0, 0.3)');
  container.style('border', '1px solid #444');
  container.style('border-radius', '5px');
  container.style('padding', '10px');
  container.style('font-family', 'monospace');
  container.style('display', 'none');
  container.style('z-index', '1000');

  let titleBar = createDiv('GLSL Fragment Shader Editor');
  titleBar.parent(container);
  titleBar.style('color', '#fff');
  titleBar.style('margin-bottom', '10px');
  titleBar.style('font-size', '14px');

  shaderEditor = createElement('textarea', neuralNoiseFrag);
  shaderEditor.parent(container);
  shaderEditor.style('width', '100%');
  shaderEditor.style('height', '400px');
  shaderEditor.style('background', 'rgba(26, 26, 26, 0.6)');
  shaderEditor.style('color', '#0f0');
  shaderEditor.style('border', '1px solid #333');
  shaderEditor.style('font-family', 'monospace');
  shaderEditor.style('font-size', '12px');
  shaderEditor.style('padding', '5px');
  shaderEditor.style('white-space', 'pre');
  shaderEditor.style('overflow-wrap', 'normal');
  shaderEditor.style('overflow-x', 'auto');

  errorDisplay = createDiv('');
  errorDisplay.parent(container);
  errorDisplay.style('color', '#f00');
  errorDisplay.style('margin-top', '10px');
  errorDisplay.style('font-size', '12px');
  errorDisplay.style('white-space', 'pre-wrap');

  let buttonContainer = createDiv();
  buttonContainer.parent(container);
  buttonContainer.style('margin-top', '10px');

  let compileBtn = createButton('Compile (Ctrl+Enter)');
  compileBtn.parent(buttonContainer);
  compileBtn.style('background', '#0a0');
  compileBtn.style('color', '#fff');
  compileBtn.style('border', 'none');
  compileBtn.style('padding', '5px 10px');
  compileBtn.style('margin-right', '10px');
  compileBtn.style('cursor', 'pointer');
  compileBtn.mousePressed(compileShader);

  let resetBtn = createButton('Reset');
  resetBtn.parent(buttonContainer);
  resetBtn.style('background', '#a00');
  resetBtn.style('color', '#fff');
  resetBtn.style('border', 'none');
  resetBtn.style('padding', '5px 10px');
  resetBtn.style('margin-right', '10px');
  resetBtn.style('cursor', 'pointer');
  resetBtn.mousePressed(() => {
    shaderEditor.value(neuralNoiseFrag);
    compileShader();
  });

  let closeBtn = createButton('Close');
  closeBtn.parent(buttonContainer);
  closeBtn.style('background', '#444');
  closeBtn.style('color', '#fff');
  closeBtn.style('border', 'none');
  closeBtn.style('padding', '5px 10px');
  closeBtn.style('cursor', 'pointer');
  closeBtn.mousePressed(toggleEditor);

  shaderEditor.elt.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      compileShader();
    }
  });
}

function compileShader() {
  const newFragCode = shaderEditor.value();

  try {
    const newShader = createShader(vert, newFragCode);
    theShader = newShader;
    lastValidFrag = newFragCode;
    errorDisplay.html('✓ Shader compiled successfully');
    errorDisplay.style('color', '#0f0');
  } catch (error) {
    errorDisplay.html('✗ Compilation error:\n' + error.message);
    errorDisplay.style('color', '#f00');

    try {
      theShader = createShader(vert, lastValidFrag);
    } catch (e) {
      console.error('Failed to restore last valid shader:', e);
    }
  }
}

function toggleEditor() {
  editorVisible = !editorVisible;
  var container = select('#editor-container');
  if (container) {
    container.style('display', editorVisible ? 'block' : 'none');
  }
}

let time = 0;

function draw() {
  // Perlin drift
  noiseOffsetA += driftSpeed;
  noiseOffsetB += driftSpeed;
  noiseOffsetC += driftSpeed;

  const driftA = map(noise(noiseOffsetA), 0, 1, 0.5 - driftAmount, 0.5 + driftAmount);
  const driftB = map(noise(noiseOffsetB), 0, 1, 0.5 - driftAmount, 0.5 + driftAmount);
  const driftC = map(noise(noiseOffsetC), 0, 1, 0.5 - driftAmount, 0.5 + driftAmount);

  paramA.set(driftA);
  paramB.set(driftB);
  paramC.set(driftC);

  paramA.update();
  paramB.update();
  paramC.update();

  time += 0.0001;

  shader(theShader);

  theShader.setUniform('resolution', [width, height]);
  theShader.setUniform('time', time);
  theShader.setUniform('paramA', constrain(paramA.value, 0, 1));
  theShader.setUniform('paramB', constrain(paramB.value, 0, 1));
  theShader.setUniform('paramC', constrain(paramC.value, 0, 1));

  rect(0, 0, width, height);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
  if (key === ' ') {
    paramA.impulse(random(-0.5, 0.5));
    paramB.impulse(random(-0.5, 0.5));
    paramC.impulse(random(-0.5, 0.5));
  }

  if (key === 'e' || key === 'E') {
    toggleEditor();
  }
}

