class MIDIController extends EventTarget {
  constructor() {
    super();
    this.midi = null;
    this.input = null;
    this.mappings = new Map();
    this.learning = null;
    this.learnCallback = null;
    this.init();
  }

  async init() {
    if (!navigator.requestMIDIAccess) {
      throw new Error('WebMIDI not supported');
    }

    try {
      this.midi = await navigator.requestMIDIAccess();
      const inputs = Array.from(this.midi.inputs.values());

      if (inputs.length > 0) {
        this.connectInput(inputs[0]);
      }

      this.midi.onstatechange = (e) => {
        if (e.port.type === 'input') {
          if (e.port.state === 'connected') {
            this.connectInput(e.port);
          } else if (e.port.state === 'disconnected' && e.port === this.input) {
            this.input = null;
            this.dispatchEvent(new CustomEvent('disconnected'));
          }
        }
      };
    } catch (error) {
      throw new Error(`MIDI initialization failed: ${error}`);
    }
  }

  connectInput(input) {
    this.input = input;
    this.input.onmidimessage = this.handleMessage.bind(this);
    this.dispatchEvent(new CustomEvent('connected', { detail: input.name }));
  }

  handleMessage(message) {
    const [status, data1, data2] = message.data;
    const type = status & 0xf0;
    const channel = status & 0x0f;

    // Skip MIDI clock
    if (status === 248) return;

    const eventData = { channel };

    switch (type) {
      case 144: // Note On
        if (data2 > 0) {
          eventData.note = data1;
          eventData.velocity = data2;
          this.handleNoteOn(eventData);
        } else {
          // Note On with velocity 0 = Note Off
          eventData.note = data1;
          eventData.velocity = 0;
          this.handleNoteOff(eventData);
        }
        break;

      case 128: // Note Off
        eventData.note = data1;
        eventData.velocity = data2;
        this.handleNoteOff(eventData);
        break;

      case 176: // Control Change
        eventData.cc = data1;
        eventData.value = data2;
        this.handleCC(eventData);
        break;

      case 224: // Pitch Bend
        eventData.value = (data2 << 7) | data1;
        this.dispatchEvent(new CustomEvent('pitchbend', { detail: eventData }));
        break;
    }

    // Handle learning mode
    if (this.learning && this.learnCallback) {
      const mapping = this.createMappingFromMessage(type, eventData);
      if (mapping) {
        this.learnCallback(mapping);
        this.learning = null;
        this.learnCallback = null;
      }
    }
  }

  createMappingFromMessage(type, data) {
    if (type === 144 || type === 128) {
      return {
        type: 'note',
        channel: data.channel,
        number: data.note,
        callback: () => {}
      };
    } else if (type === 176) {
      return {
        type: 'cc',
        channel: data.channel,
        number: data.cc,
        callback: () => {}
      };
    }
    return null;
  }

  handleNoteOn(data) {
    this.dispatchEvent(new CustomEvent('noteon', { detail: data }));

    // Check mapped callbacks
    const key = `note:${data.channel}:${data.note}`;
    var mapping = this.mappings.get(key);
    if (mapping) {
      mapping.callback(data);
    }

    // Check wildcard channel
    const wildcardKey = `note:*:${data.note}`;
    const wildcardMapping = this.mappings.get(wildcardKey);
    if (wildcardMapping) {
      wildcardMapping.callback(data);
    }
  }

  handleNoteOff(data) {
    this.dispatchEvent(new CustomEvent('noteoff', { detail: data }));
  }

  handleCC(data) {
    this.dispatchEvent(new CustomEvent('cc', { detail: data }));

    // Check mapped callbacks
    var key = `cc:${data.channel}:${data.cc}`;
    var mapping = this.mappings.get(key);
    if (mapping) {
      mapping.callback(data.value);
    }

    // Check wildcard channel
    var wildcardKey = `cc:*:${data.cc}`;
    var wildcardMapping = this.mappings.get(wildcardKey);
    if (wildcardMapping) {
      wildcardMapping.callback(data.value);
    }
  }

  // Public API

  on(event, callback) {
    this.addEventListener(event, callback);
    return () => this.removeEventListener(event, callback);
  }

  onNote(note, callback, channel) {
    var key = `note:${channel ?? '*'}:${note}`;
    this.mappings.set(key, {
      type: 'note',
      channel,
      number: note,
      callback
    });
    return () => this.mappings.delete(key);
  }

  onCC(cc, callback, channel) {
    var key = `cc:${channel ?? '*'}:${cc}`;
    this.mappings.set(key, {
      type: 'cc',
      channel,
      number: cc,
      callback
    });
    return () => this.mappings.delete(key);
  }

  learn(name) {
    return new Promise((resolve) => {
      this.learning = name;
      this.learnCallback = (mapping) => {
        mapping.callback = () => {};
        resolve(mapping);
      };
    });
  }

  async learnAndMap(name, callback) {
    var mapping = await this.learn(name);
    mapping.callback = callback;

    var key = `${mapping.type}:${mapping.channel ?? '*'}:${mapping.number}`;
    this.mappings.set(key, mapping);
  }

  getDevices() {
    if (!this.midi) return [];
    return Array.from(this.midi.inputs.values());
  }

  selectDevice(input) {
    this.connectInput(input);
  }

  disconnect() {
    if (this.input) {
      this.input.onmidimessage = null;
      this.input = null;
    }
  }
}

// Global instance for p5.js sketches
let midi;

// P5.js integration
function setupMIDI() {
  midi = new MIDIController();
  return midi;
}

